Index: qml/EditorPanel.qml
===================================================================
--- qml/EditorPanel.qml	
+++ qml/EditorPanel.qml	
@@ -1,540 +1,546 @@
+// Copyright (c) 2026-present, Dwyco, Inc.
+//
+// This Source Code Form is subject to the terms of the Mozilla Public
+// License, v. 2.0. If a copy of the MPL was not distributed with this file,
+// You can obtain one at https://mozilla.org/MPL/2.0/.
+
 import QtQuick
 import QtQuick.Controls
 import QtQuick.Layouts
 import PoisonLog 1.0

 Frame {
     id: root
     padding: 0

     property var colorPalette: [
         "#2e7d32", "#f9a825", "#ef6c00", "#c62828",
         "#1565c0", "#6a1b9a", "#00838f", "#4e342e"
     ]

     background: Rectangle {
         color: "#ffffff"
         radius: 8
         border.color: "#dfe6e1"
     }

     ColumnLayout {
         anchors.fill: parent
         anchors.margins: 14
         spacing: 10

         RowLayout {
             Layout.fillWidth: true
             Label {
                 text: App.mode === "draft" ? "Treatment details"
                     : App.mode === "record-edit" ? "Edit saved treatment"
                     : "Saved treatment"
                 font.pixelSize: 18
                 font.bold: true
                 color: "#24382a"
             }
             Item {
                 Layout.fillWidth: true
             }
             Label {
                 visible: App.mode === "draft"
                 text: "Draft"
                 color: "#6b7c70"
                 font.pixelSize: 11
             }
             Label {
                 visible: App.mode === "record-edit"
                 text: "Unsaved edits"
                 color: "#b71c1c"
                 font.pixelSize: 11
             }
         }

         StackLayout {
             Layout.fillWidth: true
             Layout.fillHeight: true
             currentIndex: App.mode === "draft" ? 0
                 : App.mode === "record-edit" ? 2
                 : 1

             ColumnLayout {
                 id: draftPane
                 Layout.fillWidth: true
                 Layout.fillHeight: true
                 spacing: 8

                 Connections {
                     target: App
                     function onDraftDateChanged() {
                         if (!dateField.activeFocus)
                             dateField.text = App.draftDate
                     }
                     function onDraftTagChanged() {
                         if (!tagField.activeFocus)
                             tagField.text = App.draftTag
                     }
                     function onDraftNotesChanged() {
                         if (!notesArea.activeFocus)
                             notesArea.text = App.draftNotes
                     }
                 }

                 RowLayout {
                     Layout.fillWidth: true
                     spacing: 8

                     Label {
                         text: "Date"
                         Layout.preferredWidth: 48
                         color: "#44554a"
                     }
                     TextField {
                         id: dateField
                         Layout.fillWidth: true
                         text: App.draftDate
                         placeholderText: "YYYY-MM-DD"
                         selectByMouse: true
                         onTextChanged: {
                             if (activeFocus && text !== App.draftDate)
                                 App.draftDate = text
                         }
                     }
                     Button {
                         text: "Today"
                         onClicked: {
                             App.draftDate = Qt.formatDate(new Date(), "yyyy-MM-dd")
                             dateField.text = App.draftDate
                         }
                     }
                 }

                 RowLayout {
                     Layout.fillWidth: true
                     spacing: 8

                     Label {
                         text: "Tag"
                         Layout.preferredWidth: 48
                         color: "#44554a"
                     }
                     TextField {
                         id: tagField
                         Layout.fillWidth: true
                         text: App.draftTag
                         placeholderText: "e.g. glyphosate, fertilizer"
                         selectByMouse: true
                         onTextChanged: {
                             if (activeFocus && text !== App.draftTag)
                                 App.draftTag = text
                         }
                     }
                 }

                 Label {
                     text: "Color for new rectangles"
                     color: "#44554a"
                 }

                 Flow {
                     Layout.fillWidth: true
                     spacing: 8

                     Repeater {
                         model: root.colorPalette
                         delegate: Rectangle {
                             width: 28
                             height: 28
                             radius: 14
                             color: modelData
                             border.width: App.draftColor.toLowerCase() === modelData ? 3 : 1
                             border.color: App.draftColor.toLowerCase() === modelData
                                           ? "#263238" : "#ffffff"

                             MouseArea {
                                 anchors.fill: parent
                                 onClicked: App.draftColor = modelData
                             }
                         }
                     }
                 }

                 Label {
                     Layout.topMargin: 4
                     text: "Notes — what was applied, how much, and any other details"
                     color: "#44554a"
                     wrapMode: Text.WordWrap
                     Layout.fillWidth: true
                 }

                 ScrollView {
                     Layout.fillWidth: true
                     Layout.fillHeight: true
                     clip: true

                     TextArea {
                         id: notesArea
                         width: parent.width
                         text: App.draftNotes
                         placeholderText: "Describe the treatment…"
                         wrapMode: TextEdit.Wrap
                         selectByMouse: true
                         onTextChanged: {
                             if (activeFocus && text !== App.draftNotes)
                                 App.draftNotes = text
                         }
                     }
                 }

                 RowLayout {
                     Layout.fillWidth: true
                     spacing: 6

                     Label {
                         text: App.rectangleCount + " rectangle(s)"
                         color: "#5e7064"
                     }
                     Item {
                         Layout.fillWidth: true
                     }
                     Button {
                         text: "Delete selected"
                         enabled: App.hasSelectedRectangle
                         onClicked: App.deleteSelectedRectangle()
                     }
                 }

                 Label {
                     Layout.fillWidth: true
                     text: "Drag on the map to draw a rectangle. Drag a rectangle to move it, "
                           + "or its lower-right corner to resize it."
                     color: "#849287"
                     font.pixelSize: 11
                     wrapMode: Text.WordWrap
                 }

                 Button {
                     Layout.fillWidth: true
                     text: "Save treatment"
                     enabled: App.canCommit
                     highlighted: true
                     onClicked: App.commitDraft()
                 }

                 Button {
                     Layout.fillWidth: true
                     text: "Reset draft"
                     onClicked: resetDraftDialog.open()
                 }

                 Label {
                     Layout.fillWidth: true
                     text: "Changes are saved automatically."
                     color: "#849287"
                     font.pixelSize: 11
                     horizontalAlignment: Text.AlignHCenter
                 }
             }

             ColumnLayout {
                 id: recordPane
                 Layout.fillWidth: true
                 Layout.fillHeight: true
                 spacing: 10

                 RowLayout {
                     Layout.fillWidth: true
                     spacing: 10

                     Rectangle {
                         Layout.preferredWidth: 14
                         Layout.preferredHeight: 14
                         radius: 7
                         color: App.viewedRecord.color || "#2e7d32"
                     }
                     Label {
                         Layout.fillWidth: true
                         text: App.viewedRecord.tag || ""
                         font.pixelSize: 17
                         font.bold: true
                         color: "#24382a"
                         elide: Text.ElideRight
                     }
                     Label {
                         text: App.viewedRecord.date || ""
                         color: "#5e7064"
                     }
                 }

                 Label {
                     text: "Notes"
                     color: "#44554a"
                 }

                 ScrollView {
                     Layout.fillWidth: true
                     Layout.fillHeight: true
                     clip: true

                     TextArea {
                         width: parent.width
                         text: App.viewedRecord.notes || ""
                         readOnly: true
                         wrapMode: TextEdit.Wrap
                         selectByMouse: true
                     }
                 }

                 Label {
                     Layout.fillWidth: true
                     visible: App.draftHasContent
                     text: "Your unfinished draft is still saved."
                     color: "#6b7c70"
                     font.pixelSize: 11
                     wrapMode: Text.WordWrap
                 }

                 Button {
                     Layout.fillWidth: true
                     text: "Edit record"
                     highlighted: true
                     onClicked: App.startRecordEdit()
                 }

                 Button {
                     Layout.fillWidth: true
                     text: "Edit draft"
                     onClicked: App.resumeDraft()
                 }

                 Button {
                     Layout.fillWidth: true
                     text: "Delete record"
                     onClicked: deleteRecordDialog.open()
                 }
             }

             ColumnLayout {
                 id: editPane
                 Layout.fillWidth: true
                 Layout.fillHeight: true
                 spacing: 8

                 Connections {
                     target: App
                     function onEditDateChanged() {
                         if (!editDateField.activeFocus)
                             editDateField.text = App.editDate
                     }
                     function onEditTagChanged() {
                         if (!editTagField.activeFocus)
                             editTagField.text = App.editTag
                     }
                     function onEditNotesChanged() {
                         if (!editNotesArea.activeFocus)
                             editNotesArea.text = App.editNotes
                     }
                 }

                 RowLayout {
                     Layout.fillWidth: true
                     spacing: 8

                     Label {
                         text: "Date"
                         Layout.preferredWidth: 48
                         color: "#44554a"
                     }
                     TextField {
                         id: editDateField
                         Layout.fillWidth: true
                         text: App.editDate
                         placeholderText: "YYYY-MM-DD"
                         selectByMouse: true
                         onTextChanged: {
                             if (activeFocus && text !== App.editDate)
                                 App.editDate = text
                         }
                     }
                     Button {
                         text: "Today"
                         onClicked: {
                             App.editDate = Qt.formatDate(new Date(), "yyyy-MM-dd")
                             editDateField.text = App.editDate
                         }
                     }
                 }

                 RowLayout {
                     Layout.fillWidth: true
                     spacing: 8

                     Label {
                         text: "Tag"
                         Layout.preferredWidth: 48
                         color: "#44554a"
                     }
                     TextField {
                         id: editTagField
                         Layout.fillWidth: true
                         text: App.editTag
                         placeholderText: "e.g. glyphosate, fertilizer"
                         selectByMouse: true
                         onTextChanged: {
                             if (activeFocus && text !== App.editTag)
                                 App.editTag = text
                         }
                     }
                 }

                 Label {
                     text: "Color for new rectangles"
                     color: "#44554a"
                 }

                 Flow {
                     Layout.fillWidth: true
                     spacing: 8

                     Repeater {
                         model: root.colorPalette
                         delegate: Rectangle {
                             width: 28
                             height: 28
                             radius: 14
                             color: modelData
                             border.width: App.editColor.toLowerCase() === modelData ? 3 : 1
                             border.color: App.editColor.toLowerCase() === modelData
                                           ? "#263238" : "#ffffff"

                             MouseArea {
                                 anchors.fill: parent
                                 onClicked: App.editColor = modelData
                             }
                         }
                     }
                 }

                 Label {
                     Layout.topMargin: 4
                     text: "Notes — what was applied, how much, and any other details"
                     color: "#44554a"
                     wrapMode: Text.WordWrap
                     Layout.fillWidth: true
                 }

                 ScrollView {
                     Layout.fillWidth: true
                     Layout.fillHeight: true
                     clip: true

                     TextArea {
                         id: editNotesArea
                         width: parent.width
                         text: App.editNotes
                         placeholderText: "Describe the treatment…"
                         wrapMode: TextEdit.Wrap
                         selectByMouse: true
                         onTextChanged: {
                             if (activeFocus && text !== App.editNotes)
                                 App.editNotes = text
                         }
                     }
                 }

                 RowLayout {
                     Layout.fillWidth: true
                     spacing: 6

                     Label {
                         text: App.rectangleCount + " rectangle(s)"
                         color: "#5e7064"
                     }
                     Item {
                         Layout.fillWidth: true
                     }
                     Button {
                         text: "Delete selected"
                         enabled: App.hasSelectedRectangle
                         onClicked: App.deleteSelectedRectangle()
                     }
                 }

                 Label {
                     Layout.fillWidth: true
                     text: "Drag on the map to draw a rectangle. Drag a rectangle to move it, "
                           + "or its lower-right corner to resize it."
                     color: "#849287"
                     font.pixelSize: 11
                     wrapMode: Text.WordWrap
                 }

                 RowLayout {
                     Layout.fillWidth: true
                     spacing: 6

                     Button {
                         text: "Cancel"
                         onClicked: App.cancelRecordEdit()
                     }
                     Button {
                         Layout.fillWidth: true
                         text: "Save changes"
                         enabled: App.canSaveEdit
                         highlighted: true
                         onClicked: App.saveRecordEdit()
                     }
                 }

                 Label {
                     Layout.fillWidth: true
                     text: "Unsaved edits are forgotten if you cancel or save elsewhere."
                     color: "#849287"
                     font.pixelSize: 11
                     horizontalAlignment: Text.AlignHCenter
                     wrapMode: Text.WordWrap
                 }
             }
         }

         Label {
             Layout.fillWidth: true
             visible: App.errorMessage.length > 0
             text: App.errorMessage
             color: "#b71c1c"
             wrapMode: Text.WordWrap
             font.pixelSize: 12
         }
     }

     Dialog {
         id: resetDraftDialog
         anchors.centerIn: parent
         modal: true
         title: "Discard the unfinished draft?"
         standardButtons: Dialog.Ok | Dialog.Cancel

         onAccepted: App.clearDraft()

         Label {
             width: parent.width
             wrapMode: Text.WordWrap
             text: "All unfinished notes and rectangles will be deleted. Saved treatments will not be changed."
         }
     }

     Dialog {
         id: deleteRecordDialog
         anchors.centerIn: parent
         modal: true
         title: "Delete this record?"
         standardButtons: Dialog.Ok | Dialog.Cancel

         onAccepted: App.deleteViewedRecord()

         Label {
             width: parent.width
             wrapMode: Text.WordWrap
             text: "The saved treatment and its rectangles on the map will be permanently deleted. This cannot be undone."
         }
     }
 }

Index: qml/Main.qml
===================================================================
--- qml/Main.qml	
+++ qml/Main.qml	
@@ -1,204 +1,210 @@
+// Copyright (c) 2026-present, Dwyco, Inc.
+//
+// This Source Code Form is subject to the terms of the Mozilla Public
+// License, v. 2.0. If a copy of the MPL was not distributed with this file,
+// You can obtain one at https://mozilla.org/MPL/2.0/.
+
 import QtQuick
 import QtQuick.Controls
 import QtQuick.Dialogs
 import QtQuick.Layouts
 import PoisonLog 1.0

 ApplicationWindow {
     id: window
     width: 1400
     height: 900
     minimumWidth: 1050
     minimumHeight: 720
     visible: true
     title: "Poison Log"
     color: "#f2f5f3"

     header: ToolBar {
         visible: App.hasMap

         background: Rectangle {
             color: "#eef3ef"
             Rectangle {
                 width: parent.width
                 height: 1
                 anchors.bottom: parent.bottom
                 color: "#d7e0d9"
             }
         }

         RowLayout {
             anchors.fill: parent
             anchors.leftMargin: 16
             anchors.rightMargin: 16
             spacing: 12

             Label {
                 text: "Poison Log"
                 font.pixelSize: 20
                 font.bold: true
                 color: "#1b5e20"
             }

             Rectangle {
                 Layout.preferredWidth: 1
                 Layout.preferredHeight: 24
                 color: "#d7e0d9"
             }

             Label {
                 Layout.maximumWidth: 460
                 text: App.mapAddress
                 elide: Text.ElideRight
                 color: "#4a5d4f"
             }

             Item {
                 Layout.fillWidth: true
             }

             Label {
                 Layout.maximumWidth: 320
                 text: App.errorMessage.length > 0 ? App.errorMessage : App.statusMessage
                 color: App.errorMessage.length > 0 ? "#b71c1c" : "#647568"
                 font.pixelSize: 12
                 elide: Text.ElideRight
             }

             Button {
                 text: "Edit draft"
                 visible: App.mode === "record"
                 onClicked: App.resumeDraft()
             }

             Button {
                 text: "Clear draft"
                 visible: App.draftHasContent || App.mode === "draft"
                 enabled: App.draftHasContent
                 onClicked: clearDraftDialog.open()
             }

             ToolButton {
                 text: "Settings"
                 ToolTip.visible: hovered
                 ToolTip.delay: 500
                 ToolTip.text: "Backup settings"
                 onClicked: settingsDialog.open()
             }
         }
     }

     StackLayout {
         anchors.fill: parent
         currentIndex: App.hasMap ? 0 : 1

         Item {
             id: mainPage

             RowLayout {
                 anchors.fill: parent
                 anchors.margins: 14
                 spacing: 14

                 RecordList {
                     Layout.preferredWidth: 320
                     Layout.fillHeight: true
                 }

                 Item {
                     Layout.fillWidth: true
                     Layout.fillHeight: true

                     MapView {
                         anchors.centerIn: parent
                         width: Math.min(parent.width, parent.height)
                         height: width
                     }
                 }

                 EditorPanel {
                     Layout.preferredWidth: 370
                     Layout.fillHeight: true
                 }
             }
         }

         MapSetupPage {
             id: setupPage
         }
     }

     Shortcut {
         sequences: [StandardKey.Delete]
         enabled: App.mode === "draft" && App.hasSelectedRectangle
         onActivated: App.deleteSelectedRectangle()
     }

     Dialog {
         id: clearDraftDialog
         anchors.centerIn: parent
         modal: true
         title: "Discard the unfinished draft?"
         standardButtons: Dialog.Ok | Dialog.Cancel

         onAccepted: App.clearDraft()

         Label {
             width: parent.width
             wrapMode: Text.WordWrap
             text: "All unfinished notes and rectangles will be deleted. Saved treatments will not be changed."
         }
     }

     Dialog {
         id: settingsDialog
         anchors.centerIn: parent
         modal: true
         title: "Backup settings"
         standardButtons: Dialog.Ok | Dialog.Cancel
         width: 520

         FolderDialog {
             id: backupFolderDialog
             title: "Choose the backup folder"
             onAccepted: {
                 let path = selectedFolder.toString().replace(/^file:\/\//, "")
                 path = path.replace(/^\/([A-Za-z]:)/, "$1")
                 backupFolderField.text = decodeURIComponent(path)
             }
         }

         onAccepted: App.backupFolder = backupFolderField.text

         ColumnLayout {
             width: parent.width
             spacing: 8

             Label {
                 text: "Backups are created every time Poison Log is closed. " +
                       "The folder will contain the database and the map image, " +
                       "ready to be copied to another machine."
                 wrapMode: Text.WordWrap
                 Layout.fillWidth: true
                 color: "#53645a"
             }

             RowLayout {
                 Layout.fillWidth: true
                 spacing: 8

                 TextField {
                     id: backupFolderField
                     Layout.fillWidth: true
                     text: App.backupFolder
                     selectByMouse: true
                 }

                 Button {
                     text: "Browse…"
                     onClicked: backupFolderDialog.open()
                 }
             }
         }
     }
 }

Index: qml/MapCanvas.qml
===================================================================
--- qml/MapCanvas.qml	
+++ qml/MapCanvas.qml	
@@ -1,199 +1,205 @@
+// Copyright (c) 2026-present, Dwyco, Inc.
+//
+// This Source Code Form is subject to the terms of the Mozilla Public
+// License, v. 2.0. If a copy of the MPL was not distributed with this file,
+// You can obtain one at https://mozilla.org/MPL/2.0/.
+
 import QtQuick

 Item {
     id: root
     objectName: "mapCanvas"
     clip: true

     property real centerLat: 0
     property real centerLon: 0
     property real groundSpanMeters: 70
     property real zoomFactor: 1
     property string attribution: "USGS, USDA — The National Map: Orthoimagery"
     property bool active: true

     readonly property real effectiveGroundSpanMeters: groundSpanMeters / Math.max(zoomFactor, 1e-6)
     readonly property real effectiveZoom: {
         const mppAtZoomZero = 156543.03392 * Math.cos(centerLat * Math.PI / 180)
         return Math.log(Math.max(1e-9, mppAtZoomZero * Math.max(width, 1) / effectiveGroundSpanMeters))
             / Math.LN2
     }
     readonly property int tileZoom: Math.max(1, Math.min(19, Math.floor(effectiveZoom)))
     readonly property real tileScale: Math.pow(2, effectiveZoom - tileZoom)
     readonly property real tileDisplaySize: 256 * tileScale
     readonly property real centerWorldX: lonToWorldX(centerLon, effectiveZoom)
     readonly property real centerWorldY: latToWorldY(centerLat, effectiveZoom)
     readonly property real tileCenterWorldX: lonToWorldX(centerLon, tileZoom)
     readonly property real tileCenterWorldY: latToWorldY(centerLat, tileZoom)
     readonly property real tileHalfWidthWorld: (width / 2) / Math.max(tileScale, 1e-9)
     readonly property real tileHalfHeightWorld: (height / 2) / Math.max(tileScale, 1e-9)
     readonly property int visibleMinTileX: Math.floor((tileCenterWorldX - tileHalfWidthWorld) / 256)
     readonly property int visibleMaxTileX: Math.floor((tileCenterWorldX + tileHalfWidthWorld) / 256)
     readonly property int visibleMinTileY: Math.floor((tileCenterWorldY - tileHalfHeightWorld) / 256)
     readonly property int visibleMaxTileY: Math.floor((tileCenterWorldY + tileHalfHeightWorld) / 256)
     property var tileItems: []
     property bool tilesReady: false

     function normalizeLon(lon) {
         return ((lon + 180) % 360 + 360) % 360 - 180
     }

     function lonToWorldX(lon, zoom) {
         return (normalizeLon(lon) + 180) / 360 * 256 * Math.pow(2, zoom)
     }

     function latToWorldY(lat, zoom) {
         const clamped = Math.max(-85.05112878, Math.min(85.05112878, lat))
         const radians = clamped * Math.PI / 180
         return (1 - Math.log(Math.tan(radians) + 1 / Math.cos(radians)) / Math.PI)
             / 2 * 256 * Math.pow(2, zoom)
     }

     function computeTiles() {
         if (!active || width <= 0 || height <= 0 || !isFinite(effectiveZoom))
             return []

         const zoom = tileZoom
         const minX = visibleMinTileX
         const maxX = visibleMaxTileX
         const minY = visibleMinTileY
         const maxY = visibleMaxTileY
         const tileCount = 1 << zoom
         const result = []

         for (let tileY = minY; tileY <= maxY; ++tileY) {
             if (tileY < 0 || tileY >= tileCount)
                 continue
             for (let tileX = minX; tileX <= maxX; ++tileX) {
                 const sourceX = ((tileX % tileCount) + tileCount) % tileCount
                 result.push({
                     sourceX: sourceX,
                     tileX: tileX,
                     tileY: tileY
                 })
             }
         }
         return result
     }

     function zoomIn() {
         zoomFactor = Math.min(8, zoomFactor * 2)
     }

     function zoomOut() {
         zoomFactor = Math.max(0.5, zoomFactor / 2)
     }

     function panBy(dx, dy) {
         if (!active || width <= 0 || height <= 0)
             return

         const zoom = effectiveZoom
         const worldPixels = 256 * Math.pow(2, zoom)
         const centerX = lonToWorldX(centerLon, zoom) - dx
         const centerY = latToWorldY(centerLat, zoom) - dy
         const newLon = normalizeLon(centerX / worldPixels * 360 - 180)
         const mercatorY = Math.PI - 2 * Math.PI * centerY / worldPixels
         const newLat = Math.atan(Math.sinh(mercatorY)) * 180 / Math.PI

         centerLat = Math.max(-85, Math.min(85, newLat))
         centerLon = newLon
     }

     function evaluateTileReadiness() {
         let ready = repeater.count > 0
         for (let i = 0; i < repeater.count; ++i) {
             const image = repeater.itemAt(i)
             if (!image || image.status !== Image.Ready) {
                 ready = false
                 break
             }
         }
         if (tilesReady !== ready)
             tilesReady = ready
     }

     function rebuildTiles() {
         console.warn("rebuild", width, height, tileZoom, centerLat, centerLon, visibleMinTileX, visibleMaxTileX, visibleMinTileY, visibleMaxTileY)
         tileItems = computeTiles()
     }

     onTileItemsChanged: tilesReady = false
     onVisibleMinTileXChanged: rebuildTiles()
     onVisibleMaxTileXChanged: rebuildTiles()
     onVisibleMinTileYChanged: rebuildTiles()
     onVisibleMaxTileYChanged: rebuildTiles()
     onTileZoomChanged: rebuildTiles()
     onWidthChanged: rebuildTiles()
     onHeightChanged: rebuildTiles()
     onActiveChanged: rebuildTiles()
     Component.onCompleted: rebuildTiles()

     Repeater {
         id: repeater
         model: root.tileItems
         delegate: Image {
             required property var modelData

             x: modelData.tileX * root.tileDisplaySize - root.centerWorldX + root.width / 2
             y: modelData.tileY * root.tileDisplaySize - root.centerWorldY + root.height / 2
             width: root.tileDisplaySize
             height: root.tileDisplaySize
             source: root.active
                 ? "image://tiles/" + root.tileZoom + "/" + modelData.sourceX + "/" + modelData.tileY
                 : ""
             fillMode: Image.Stretch
             asynchronous: true
             cache: true
             smooth: true
         }
     }

     MouseArea {
         anchors.fill: parent
         enabled: root.active
         acceptedButtons: Qt.LeftButton
         cursorShape: Qt.ClosedHandCursor

         property real lastX: 0
         property real lastY: 0

         onPressed: (mouse) => {
             lastX = mouse.x
             lastY = mouse.y
         }
         onPositionChanged: (mouse) => {
             if (!pressed)
                 return
             root.panBy(mouse.x - lastX, mouse.y - lastY)
             lastX = mouse.x
             lastY = mouse.y
         }
     }

     Timer {
         interval: 80
         repeat: true
         running: root.active
         onTriggered: root.evaluateTileReadiness()
     }

     Rectangle {
         z: 10
         anchors.right: parent.right
         anchors.bottom: parent.bottom
         anchors.margins: 4
         width: attributionText.implicitWidth + 10
         height: attributionText.implicitHeight + 4
         radius: 2
         color: "#e6ffffff"

         Text {
             id: attributionText
             anchors.centerIn: parent
             text: root.attribution
             font.pixelSize: 10
             color: "#304437"
         }
     }
 }

Index: qml/MapSetupPage.qml
===================================================================
--- qml/MapSetupPage.qml	
+++ qml/MapSetupPage.qml	
@@ -1,289 +1,295 @@
+// Copyright (c) 2026-present, Dwyco, Inc.
