+void AppStore::selectRecord(int recordId)
+{
+    if (!m_hasMap)
+        return;
+    if (editingRecord()) {
+        setError(QStringLiteral("Save or cancel your edits before selecting another record."));
+        return;
+    }
+
+    if (m_mode == QStringLiteral("draft")) {
+        persistDraftFields();
+        persistDraftRectangles();
+    }
+
+    QString error;
+    const auto record = m_database->record(recordId, &error);
+    if (!record) {
+        setError(error.isEmpty() ? QStringLiteral("The record could not be found.") : error);
+        return;
+    }
+
+    m_viewedRecordId = record->id;
+    m_viewedRecord = recordToMap(*record);
+    loadRecordRectangles(record->id);
+    setMode(QStringLiteral("record"));
+    emit viewedRecordChanged();
+    emit currentRectangleColorChanged();
+    setError(QString());
+    setStatus(QStringLiteral("Viewing saved treatment."));
+}
+
+void AppStore::resumeDraft()
+{
+    if (!m_hasMap)
+        return;
+    if (editingRecord()) {
+        setError(QStringLiteral("Save or cancel your edits before editing the draft."));
+        return;
+    }
+    if (!loadDraft(true)) {
+        setError(QStringLiteral("The draft could not be loaded."));
+        return;
+    }
+    resetViewedRecord();
+    setMode(QStringLiteral("draft"));
+    setError(QString());
+    setStatus(QStringLiteral("Editing the draft."));
+}
+
+void AppStore::startRecordEdit()
+{
+    if (!m_hasMap)
+        return;
+    if (m_viewedRecordId < 0 || m_viewedRecord.isEmpty()) {
+        setError(QStringLiteral("Select a record before editing it."));
+        return;
+    }
+
+    QString error;
+    const auto record = m_database->record(m_viewedRecordId, &error);
+    if (!record) {
+        setError(error.isEmpty() ? QStringLiteral("The record could not be found.") : error);
+        return;
+    }
+
+    m_editDate = record->date;
+    m_editTag = record->tag;
+    m_editNotes = record->notes;
+    m_editColor = record->color.isEmpty() ? QString::fromLatin1(Database::DefaultColor)
+                                          : record->color;
+    loadRecordRectangles(record->id);
+
+    emit editDateChanged();
+    emit editTagChanged();
+    emit editNotesChanged();
+    emit editColorChanged();
+    emit canSaveEditChanged();
+
+    setMode(QStringLiteral("record-edit"));
+    setError(QString());
+    setStatus(QStringLiteral("Editing the saved treatment."));
+}
+
+void AppStore::cancelRecordEdit()
+{
+    if (!editingRecord())
+        return;
+
+    const int recordId = m_viewedRecordId;
+    QString error;
+    const auto record = m_database->record(recordId, &error);
+    if (!record) {
+        setError(error.isEmpty() ? QStringLiteral("The record could not be reloaded.") : error);
+        return;
+    }
+
+    m_viewedRecord = recordToMap(*record);
+    loadRecordRectangles(recordId);
+    emit viewedRecordChanged();
+
+    setMode(QStringLiteral("record"));
+    emit currentRectangleColorChanged();
+    setError(QString());
+    setStatus(QStringLiteral("Edits to the record were cancelled."));
+}
+
+void AppStore::deleteViewedRecord()
+{
+    if (!m_hasMap)
+        return;
+    if (m_mode != QStringLiteral("record")) {
+        if (editingRecord())
+            setError(QStringLiteral("Save or cancel your edits before deleting the record."));
+        return;
+    }
+
+    const int recordId = m_viewedRecordId;
+    QString error;
+    if (!m_database->deleteRecord(recordId, &error)) {
+        setError(error);
+        return;
+    }
+    refreshRecords();
+    resetViewedRecord();
+
+    const bool draftRestored = loadDraft(true);
+    setMode(QStringLiteral("draft"));
+    emit currentRectangleColorChanged();
+    if (!draftRestored) {
+        setError(QStringLiteral("The draft could not be loaded after deleting the record."));
+        return;
+    }
+    setError(QString());
+    setStatus(QStringLiteral("The saved treatment was deleted."));
+}
+
+void AppStore::saveRecordEdit()
+{
+    if (!editingRecord())
+        return;
+    if (!canSaveEdit()) {
+        setError(QStringLiteral("Add at least one rectangle, a tag, and a valid date."));
+        return;
+    }
+
+    const int recordId = m_viewedRecordId;
+
+    Database::Record fields;
+    fields.date = m_editDate;
+    fields.tag = m_editTag.trimmed();
+    fields.color = m_editColor;
+    fields.notes = m_editNotes;
+
+    const QVector<MapRectangle> rectangles = m_rectangles.rectangles();
+    QVector<Database::Rect> stored;
+    stored.reserve(rectangles.size());
+    for (const MapRectangle &item : rectangles) {
+        Database::Rect rect;
+        rect.x = item.x;
+        rect.y = item.y;
+        rect.w = item.w;
+        rect.h = item.h;
+        rect.rotation = item.rotation;
+        rect.color = item.color;
+        stored.append(rect);
+    }
+
+    QString error;
+    if (!m_database->updateRecord(recordId, fields, stored, &error)) {
+        setError(error);
+        return;
+    }
+
+    refreshRecords();
+
+    const auto record = m_database->record(recordId, &error);
+    if (!record) {
+        setError(error.isEmpty() ? QStringLiteral("The record could not be reloaded.") : error);
+        return;
+    }
+
+    m_viewedRecord = recordToMap(*record);
+    loadRecordRectangles(recordId);
+    emit viewedRecordChanged();
+
+    setMode(QStringLiteral("record"));
+    emit currentRectangleColorChanged();
+    setError(QString());
+    setStatus(QStringLiteral("The saved treatment was updated."));
+}
+
+void AppStore::clearDraft()
+{
+    if (m_draftId <= 0)
+        return;
+
+    Database::Record defaults;
+    defaults.date = today();
+    QString error;
+    if (!m_database->clearDraft(m_draftId, defaults, &error)) {
+        setError(error);
+        return;
+    }
+
+    if (!loadDraft(true)) {
+        setError(QStringLiteral("The draft could not be reset."));
+        return;
+    }
+    resetViewedRecord();
+    setMode(QStringLiteral("draft"));
+    setError(QString());
+    setStatus(QStringLiteral("The unfinished draft was discarded."));
+}
+
+void AppStore::commitDraft()
+{
+    if (m_mode != QStringLiteral("draft")) {
+        setError(QStringLiteral("Save the current draft edits before saving the treatment."));
+        return;
+    }
+    if (!canCommit()) {
+        setError(QStringLiteral("Add at least one rectangle, a tag, and a valid date."));
+        return;
+    }
+
+    persistDraftFields();
+    persistDraftRectangles();
+
+    Database::Record fields;
+    fields.date = m_draftDate;
+    fields.tag = m_draftTag.trimmed();
+    fields.color = m_draftColor;
+    fields.notes = m_draftNotes;
+
+    QString error;
+    int committedId = 0;
+    if (!m_database->commitDraft(m_draftId, fields, &committedId, &error)) {
+        setError(error);
+        return;
+    }
+
+    if (!loadDraft(true))
+        return;
+    refreshRecords();
+
+    const auto committed = m_database->record(committedId, &error);
+    if (!committed) {
+        setError(error.isEmpty() ? QStringLiteral("The saved record could not be reloaded.") : error);
+        return;
+    }
+
+    m_viewedRecordId = committed->id;
+    m_viewedRecord = recordToMap(*committed);
+    loadRecordRectangles(committed->id);
+    setMode(QStringLiteral("record"));
+    emit viewedRecordChanged();
+    emit currentRectangleColorChanged();
+    setError(QString());
+    setStatus(QStringLiteral("Treatment saved."));
+}
+
+void AppStore::addDraftRectangle(double x, double y, double width, double height)
+{
+    if (m_mode != QStringLiteral("draft") && !editingRecord())
+        return;
+
+    x = clamp01(x);
+    y = clamp01(y);
+    width = std::min(clamp01(width), 1.0 - x);
+    height = std::min(clamp01(height), 1.0 - y);
+    if (width < MinimumRectangleSize || height < MinimumRectangleSize)
+        return;
+
+    MapRectangle rect;
+    rect.x = x;
+    rect.y = y;
+    rect.w = width;
+    rect.h = height;
+    rect.color = currentRectangleColor();
+    m_rectangles.addRectangle(rect);
+    if (m_mode == QStringLiteral("draft")) {
+        ++m_draftRectangleCount;
+        emit canCommitChanged();
+    }
+    m_selectedRectangleIndex = m_rectangles.count() - 1;
+    emit selectedRectangleChanged();
+    if (m_mode == QStringLiteral("draft")) {
+        persistDraftRectangles();
+        emit draftContentChanged();
+    }
+}
+
+void AppStore::updateDraftRectangle(int index, double x, double y, double width,
+                                    double height, bool persist)
+{
+    if (m_mode != QStringLiteral("draft") && !editingRecord())
+        return;
+    if (index < 0 || index >= m_rectangles.count())
+        return;
+
+    x = clamp01(x);
+    y = clamp01(y);
+    width = std::max(MinimumRectangleSize, std::min(clamp01(width), 1.0 - x));
+    height = std::max(MinimumRectangleSize, std::min(clamp01(height), 1.0 - y));
+
+    MapRectangle rect = m_rectangles.rectangles().at(index);
+    rect.x = x;
+    rect.y = y;
+    rect.w = width;
+    rect.h = height;
+    m_rectangles.setRectangle(index, rect);
+    if (persist && m_mode == QStringLiteral("draft"))
+        persistDraftRectangles();
+}
+
+void AppStore::updateDraftRectangleRotation(int index, double degrees, bool persist)
+{
+    if (m_mode != QStringLiteral("draft") && !editingRecord())
+        return;
+    if (index < 0 || index >= m_rectangles.count())
+        return;
+
+    degrees = std::fmod(degrees, 360.0);
+    if (degrees < 0.0)
+        degrees += 360.0;
+
+    MapRectangle rect = m_rectangles.rectangles().at(index);
+    rect.rotation = degrees;
+    m_rectangles.setRectangle(index, rect);
+    if (persist && m_mode == QStringLiteral("draft"))
+        persistDraftRectangles();
+}
+
+void AppStore::saveDraftRectangles()
+{
+    if (!m_rectangles.count())
+        return;
+    // In record-edit mode edits stay in memory until saveRecordEdit().
+    if (editingRecord())
+        return;
+    if (m_mode != QStringLiteral("draft"))
+        return;
+    m_draftRectangleCount = m_rectangles.count();
+    persistDraftRectangles();
+    emit draftContentChanged();
+    emit canCommitChanged();
+}
+
+void AppStore::removeDraftRectangle(int index)
+{
+    if (m_mode != QStringLiteral("draft") && !editingRecord())
+        return;
+    if (index < 0 || index >= m_rectangles.count())
+        return;
+
+    m_rectangles.removeRectangle(index);
+    if (m_mode == QStringLiteral("draft")) {
+        m_draftRectangleCount = m_rectangles.count();
+        emit canCommitChanged();
+    }
+    if (m_selectedRectangleIndex == index) {
+        m_selectedRectangleIndex = -1;
+    } else if (m_selectedRectangleIndex > index) {
+        --m_selectedRectangleIndex;
+    }
+    emit selectedRectangleChanged();
+    if (m_mode == QStringLiteral("draft")) {
+        persistDraftRectangles();
+        emit draftContentChanged();
+    }
+}
+
+void AppStore::deleteSelectedRectangle()
+{
+    if (hasSelectedRectangle())
+        removeDraftRectangle(m_selectedRectangleIndex);
+}
+
+void AppStore::selectRectangle(int index)
+{
+    if (index < 0 || index >= m_rectangles.count())
+        index = -1;
+    if (index == m_selectedRectangleIndex)
+        return;
+    m_selectedRectangleIndex = index;
+    emit selectedRectangleChanged();
+}
+
+void AppStore::reportError(const QString &message)
+{
+    setError(message);
+}
+
+void AppStore::clearMessages()
+{
+    setError(QString());
+    setStatus(QString());
+}
+
+void AppStore::loadInitialState()
+{
+    if (!loadMap()) {
+        if (m_errorMessage.isEmpty())
+            setStatus(QStringLiteral("Search for an address to create the property map."));
+        setMode(QStringLiteral("setup"));
+        return;
+    }
+
+    QString error;
+    if (!m_database->ensureDraft(&error)) {
+        setError(error);
+        setMode(QStringLiteral("setup"));
+        return;
+    }
+
+    refreshRecords();
+    if (!loadDraft(true)) {
+        setError(QStringLiteral("The draft could not be loaded."));
+        setMode(QStringLiteral("setup"));
+        return;
+    }
+
+    setMode(QStringLiteral("draft"));
+    setStatus(QStringLiteral("Restored the unfinished draft."));
+}
+
+bool AppStore::loadMap()
+{
+    QString error;
+    const auto info = m_database->map(&error);
+    if (!info) {
+        if (!error.isEmpty())
+            setError(error);
+        m_hasMap = false;
+        m_map = {};
+        return false;
+    }
+
+    m_map = *info;
+    m_hasMap = true;
+
+    // Self-heal databases that still store the image as an absolute path:
+    // rewrite it relative to the database directory whenever the image can
+    // be located in the standard layout (same install, or a restored one).
+    if (QFileInfo(m_map.imagePath).isAbsolute()) {
+        const QString relative = relativeImagePath(resolveMapImagePath(m_map.imagePath));
+        if (relative != m_map.imagePath) {
+            m_map.imagePath = relative;
+            persistMapImagePath();
+        }
+    }
+    return true;
+}
+
+QString AppStore::resolveMapImagePath(const QString &stored) const
+{
+    if (stored.isEmpty())
+        return stored;
+
+    const QFileInfo info(stored);
+    if (info.isAbsolute()) {
+        if (info.exists())
+            return stored;
+        // Toleration for a restored data folder: the image is expected to
+        // live in the standard maps/ directory next to the database.
+        return QDir(m_dataRoot).filePath(QStringLiteral("maps/") + info.fileName());
+    }
+    return QDir(m_dataRoot).filePath(stored);
+}
+
+QString AppStore::relativeImagePath(const QString &resolved) const
+{
+    const QDir dataRoot(m_dataRoot);
+    if (!QFileInfo(resolved).isAbsolute())
+        return resolved;
+    const QString relative = dataRoot.relativeFilePath(resolved);
+    if (relative.startsWith(QStringLiteral("..")))
+        return resolved;
+    return relative;
+}
+
+void AppStore::persistMapImagePath()
+{
+    if (m_map.imagePath.isEmpty())
+        return;
+    QString error;
+    if (!m_database->saveMapImagePath(m_map.imagePath, &error))
+        setError(error);
+}
+
+bool AppStore::loadDraft(bool loadRectangles)
+{
+    QString error;
+    if (!m_database->ensureDraft(&error)) {
+        setError(error);
+        return false;
+    }
+    const auto record = m_database->draft(&error);
+    if (!record) {
+        setError(error.isEmpty() ? QStringLiteral("The draft could not be loaded.") : error);
+        return false;
+    }
+
+    m_draftId = record->id;
+    m_draftDate = record->date;
+    m_draftTag = record->tag;
+    m_draftNotes = record->notes;
+    m_draftColor = record->color.isEmpty() ? QString::fromLatin1(Database::DefaultColor)
+                                           : record->color;
+    emit draftDateChanged();
+    emit draftTagChanged();
+    emit draftNotesChanged();
+    emit draftColorChanged();
+    emit draftContentChanged();
+    emit canCommitChanged();
+    emit currentRectangleColorChanged();
+
+    if (loadRectangles)
+        loadDraftRectangles();
+    return true;
+}
+
+void AppStore::loadDraftRectangles()
+{
+    if (m_draftId <= 0)
+        return;
+
+    QString error;
+    const QVector<Database::Rect> stored = m_database->rectangles(m_draftId, &error);
+    if (!error.isEmpty()) {
+        setError(error);
+        return;
+    }
+
+    QVector<MapRectangle> rectangles;
+    rectangles.reserve(stored.size());
+    for (const Database::Rect &rect : stored) {
+        MapRectangle item;
+        item.x = rect.x;
+        item.y = rect.y;
+        item.w = rect.w;
+        item.h = rect.h;
+        item.rotation = rect.rotation;
+        item.color = rect.color.isEmpty() ? m_draftColor : rect.color;
+        rectangles.append(item);
+    }
+    m_rectangles.setRectangles(rectangles);
+    m_draftRectangleCount = rectangles.size();
+    m_selectedRectangleIndex = -1;
+    emit selectedRectangleChanged();
+    emit rectangleCountChanged();
+    emit draftContentChanged();
+    emit canCommitChanged();
+}
+
+void AppStore::loadRecordRectangles(int recordId)
+{
+    QString error;
+    const QVector<Database::Rect> stored = m_database->rectangles(recordId, &error);
+    if (!error.isEmpty()) {
+        setError(error);
+        return;
+    }
+
+    QVector<MapRectangle> rectangles;
+    rectangles.reserve(stored.size());
+    const QString fallbackColor = m_viewedRecord.value(QStringLiteral("color")).toString();
+    for (const Database::Rect &rect : stored) {
+        MapRectangle item;
+        item.x = rect.x;
+        item.y = rect.y;
+        item.w = rect.w;
+        item.h = rect.h;
+        item.rotation = rect.rotation;
+        item.color = rect.color.isEmpty()
+            ? (fallbackColor.isEmpty() ? QString::fromLatin1(Database::DefaultColor)
+                                       : fallbackColor)
+            : rect.color;
+        rectangles.append(item);
+    }
+    m_rectangles.setRectangles(rectangles);
+    m_selectedRectangleIndex = -1;
+    emit selectedRectangleChanged();
+    emit rectangleCountChanged();
+    emit canCommitChanged();
+}
+
+void AppStore::refreshRecords()
+{
+    QString error;
+    const QVector<Database::Record> records = m_database->committedRecords(&error);
+    if (!error.isEmpty()) {
+        setError(error);
+        return;
+    }
+    m_records.setRecords(records);
+    emit recordCountChanged();
+}
+
+void AppStore::setMode(const QString &mode)
+{
+    if (m_mode == mode)
+        return;
+    m_mode = mode;
+    emit modeChanged();
+    emit canCommitChanged();
+    emit canSaveEditChanged();
+    emit currentRectangleColorChanged();
+}
+
+void AppStore::persistDraftFields()
+{
+    if (!m_database || !m_database->isOpen() || m_draftId <= 0)
+        return;
+
+    Database::Record fields;
+    fields.date = m_draftDate;
+    fields.tag = m_draftTag;
+    fields.color = m_draftColor;
+    fields.notes = m_draftNotes;
+
+    QString error;
+    if (!m_database->saveDraftFields(m_draftId, fields, &error))
+        setError(error);
+}
+
+void AppStore::persistDraftRectangles()
+{
+    if (!m_database || !m_database->isOpen() || m_draftId <= 0)
+        return;
+
+    const QVector<MapRectangle> rectangles = m_rectangles.rectangles();
+    QVector<Database::Rect> stored;
+    stored.reserve(rectangles.size());
+    for (const MapRectangle &item : rectangles) {
+        Database::Rect rect;
+        rect.x = item.x;
+        rect.y = item.y;
+        rect.w = item.w;
+        rect.h = item.h;
+        rect.rotation = item.rotation;
+        rect.color = item.color;
+        stored.append(rect);
+    }
+
+    QString error;
+    if (!m_database->replaceRectangles(m_draftId, stored, &error))
+        setError(error);
+}
+
+void AppStore::setStatus(const QString &message)
+{
+    if (m_statusMessage == message)
+        return;
+    m_statusMessage = message;
+    emit statusMessageChanged();
+}
+
+void AppStore::setError(const QString &message)
+{
+    if (m_errorMessage == message)
+        return;
+    m_errorMessage = message;
+    emit errorMessageChanged();
+}
+
+QString AppStore::backupFolder() const
+{
+    return m_backupFolder;
+}
+
+void AppStore::setBackupFolder(const QString &folder)
+{
+    QString normalized = folder.trimmed();
+    if (normalized.isEmpty()) {
+        normalized = QStandardPaths::writableLocation(QStandardPaths::AppDataLocation)
+            + QStringLiteral("/backups");
+    }
+    if (m_backupFolder == normalized)
+        return;
+    m_backupFolder = normalized;
+    QSettings settings;
+    settings.setValue(QStringLiteral("backup/folder"), m_backupFolder);
+    emit backupFolderChanged();
+}
+
+void AppStore::createBackup()
+{
+    if (!m_hasMap) {
+        setStatus(QStringLiteral("Nothing to back up yet: the map has not been set up."));
+        return;
+    }
+
+    const QString folder = QDir(m_backupFolder).absolutePath();
+    if (!QDir().mkpath(folder)) {
+        setError(QStringLiteral("The backup folder could not be created: %1").arg(folder));
+        return;
+    }
+
+    const QString destination = QDir(folder).filePath(QStringLiteral("poisonlog.db"));
+    QFile::remove(destination);
+    QString error;
+    if (!m_database->backupTo(destination, &error)) {
+        setError(error);
+        return;
+    }
+
+    const QFileInfo image(resolveMapImagePath(m_map.imagePath));
+    const QString relative = relativeImagePath(image.absoluteFilePath());
+    const bool mirrored = QDir::isRelativePath(relative);
+    const QString imageDestination = mirrored
+        ? QDir(folder).filePath(relative)
+        : QDir(QDir(folder).filePath(QStringLiteral("maps"))).filePath(image.fileName());
+    if (!QDir().mkpath(QFileInfo(imageDestination).absolutePath())) {
+        setError(QStringLiteral("The backup map directory could not be created: %1")
+            .arg(QFileInfo(imageDestination).absolutePath()));
+        return;
+    }
+    QFile::remove(imageDestination);
+    if (!QFile::copy(image.absoluteFilePath(), imageDestination)) {
+        setError(QStringLiteral("The map image could not be backed up to: %1")
+            .arg(imageDestination));
+        return;
+    }
+
+    if (!mirrored) {
+        // Custom image outside the data folder: keep the backed-up database
+        // row pointing at the portable maps/ layout instead of a local path.
+        Database backupDatabase(destination);
+        if (backupDatabase.open(&error))
+            backupDatabase.saveMapImagePath(
+                relativeImagePath(imageDestination), &error);
+        if (!error.isEmpty())
+            setError(error);
+    }
+
+    setStatus(QStringLiteral("Backup created in %1.").arg(folder));
+}
+
+void AppStore::resetViewedRecord()
+{
+    const bool hadRecord = m_viewedRecordId >= 0 || !m_viewedRecord.isEmpty();
+    m_viewedRecordId = -1;
+    m_viewedRecord.clear();
+    if (hadRecord) {
+        emit viewedRecordChanged();
+        emit currentRectangleColorChanged();
+    }
+}
+
+QVariantMap AppStore::recordToMap(const Database::Record &record) const
+{
+    QVariantMap map;
+    map.insert(QStringLiteral("id"), record.id);
+    map.insert(QStringLiteral("date"), record.date);
+    map.insert(QStringLiteral("tag"), record.tag);
+    map.insert(QStringLiteral("color"), record.color);
+    map.insert(QStringLiteral("notes"), record.notes);
+    map.insert(QStringLiteral("createdAt"), record.createdAt);
+    return map;
+}
+
+QString AppStore::today()
+{
+    return QDate::currentDate().toString(Qt::ISODate);
+}
+
+double AppStore::clamp01(double value)
+{
+    return std::clamp(value, 0.0, 1.0);
+}

